def num_dup_digits_at_most_n(n):
    def perm(n_val, k):
        result = 1
        for i in range(k):
            result *= (n_val - i)
        return result

    s = str(n)
    L = len(s)
    count_unique = 0
    for length in range(1, L):
        count_unique += 9 * perm(9, length - 1)         # shorter lengths: direct permutation formula

    used = [False] * 10
    for i, ch in enumerate(s):
        d = int(ch)
        start = 1 if i == 0 else 0
        for x in range(start, d):
            if used[x]:
                continue
            count_unique += perm(9 - i, L - i - 1)          # valid smaller digit at this position
        if used[d]:
            break                                              # n itself repeats a digit; stop early
        used[d] = True
        if i == L - 1:
            count_unique += 1                                  # n itself has all unique digits

    return n - count_unique

