    static int perm(int n, int k) {
        int result = 1;
        for (int i = 0; i < k; i++) result *= (n - i);
        return result;
    }

    static int numDupDigitsAtMostN(int n) {
        String s = String.valueOf(n);
        int L = s.length();
        int countUnique = 0;
        for (int len = 1; len < L; len++) countUnique += 9 * perm(9, len - 1);  // shorter lengths

        boolean[] used = new boolean[10];
        for (int i = 0; i < L; i++) {
            int d = s.charAt(i) - '0';
            int start = i == 0 ? 1 : 0;
            for (int x = start; x < d; x++) {
                if (used[x]) continue;
                countUnique += perm(9 - i, L - i - 1);        // valid smaller digit at this position
            }
            if (used[d]) break;                                    // n repeats a digit; stop early
            used[d] = true;
            if (i == L - 1) countUnique += 1;                       // n itself is all unique
        }
        return n - countUnique;
    }
}

