        int start = i == 0 ? 1 : 0;
        for (int x = start; x < d; x++) {
            if (used[x]) continue;
            countUnique += perm(9 - i, L - i - 1);            // valid smaller digit at this position
        }
        if (used[d]) break;                                        // n repeats a digit; stop early
        used[d] = true;
        if (i == L - 1) countUnique += 1;                           // n itself is all unique
